 "content": "def transform(grid):
    """Erase non-2 cells in the rows and columns crossing a 2x2 zero marker."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return out
    r, c = marker
    for rr in range(h):
        for cc in range(w):
            if rr in (r, r + 1) or cc in (c, c + 1):
                if out[rr][cc] != 2:
